<?php
require_once __DIR__.'/../app/bootstrap.php'; require_admin();
$backupDir=dirname(__DIR__).'/storage/backups'; if(!is_dir($backupDir))@mkdir($backupDir,0755,true);
function sql_value(PDO $pdo,$v): string {return $v===null?'NULL':$pdo->quote((string)$v);}
function create_sql_backup(string $file): void{
 $pdo=db();$fh=fopen($file,'wb');if(!$fh)throw new RuntimeException('No se pudo crear el archivo SQL.');
 fwrite($fh,"-- ComercioSocial backup\n-- Fecha: ".date(DATE_ATOM)."\nSET FOREIGN_KEY_CHECKS=0;\nSET NAMES utf8mb4;\n\n");
 $tables=$pdo->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_NUM);
 foreach($tables as $row){$table=$row[0];$safe=str_replace('`','``',$table);$create=$pdo->query("SHOW CREATE TABLE `{$safe}`")->fetch(PDO::FETCH_NUM);fwrite($fh,"DROP TABLE IF EXISTS `{$safe}`;\n".$create[1].";\n\n");
  $st=$pdo->query("SELECT * FROM `{$safe}`");while($data=$st->fetch(PDO::FETCH_ASSOC)){ $cols=array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',array_keys($data));$vals=array_map(fn($v)=>sql_value($pdo,$v),array_values($data));fwrite($fh,"INSERT INTO `{$safe}` (".implode(',',$cols).") VALUES (".implode(',',$vals).");\n");}fwrite($fh,"\n");
 }
 fwrite($fh,"SET FOREIGN_KEY_CHECKS=1;\n");fclose($fh);
}
function zip_tree(ZipArchive $zip,string $dir,string $prefix): void{if(!is_dir($dir))return;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if($f->isFile())$zip->addFile($f->getPathname(),$prefix.'/'.str_replace('\\','/',substr($f->getPathname(),strlen($dir)+1)));}}
if(isset($_GET['download'])){$name=basename((string)$_GET['download']);$file=$backupDir.'/'.$name;if(!is_file($file)||!preg_match('/\.(sql|zip)$/',$name)){http_response_code(404);exit('Archivo no encontrado');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($file));readfile($file);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='create'){$type=($_POST['backup_type']??'database')==='complete'?'complete':'database';$stamp=date('Y-m-d_H-i-s');$sql=$backupDir.'/comerciosocial_'.$stamp.'.sql';create_sql_backup($sql);$result=basename($sql);
  if($type==='complete'){if(!class_exists('ZipArchive'))throw new RuntimeException('La extensión ZIP no está habilitada.');$zipName=$backupDir.'/comerciosocial_completo_'.$stamp.'.zip';$zip=new ZipArchive();if($zip->open($zipName,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('No se pudo crear el ZIP.');$zip->addFile($sql,'database/database.sql');zip_tree($zip,dirname(__DIR__).'/public/uploads','public/uploads');if(isset($_POST['include_config'])&&is_file(dirname(__DIR__).'/config/config.php'))$zip->addFile(dirname(__DIR__).'/config/config.php','config/config.php');$zip->addFromString('backup-info.json',json_encode(['created_at'=>date(DATE_ATOM),'site'=>setting('site_name',APP_NAME),'database'=>DB_NAME,'includes'=>['database','uploads',isset($_POST['include_config'])?'config':'']],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$zip->close();@unlink($sql);$result=basename($zipName);}audit_log('backup.created','backup',$result,['type'=>$type]);flash('success','Copia creada: '.$result);
 }
 if($action==='delete'){$name=basename((string)$_POST['file']);if(preg_match('/\.(sql|zip)$/',$name)&&is_file($backupDir.'/'.$name))@unlink($backupDir.'/'.$name);audit_log('backup.deleted','backup',$name);flash('success','Copia eliminada.');}
 }catch(Throwable $e){flash('error',$e->getMessage());}redirect('../admin/backups.php');}
$files=[];foreach(glob($backupDir.'/*.{sql,zip}',GLOB_BRACE)?:[] as $f)$files[]=['name'=>basename($f),'size'=>filesize($f),'time'=>filemtime($f),'type'=>pathinfo($f,PATHINFO_EXTENSION)];usort($files,fn($a,$b)=>$b['time']<=>$a['time']);
$adminPage='backups';$adminTitle='Copias de seguridad';$adminSubtitle='Exporta la base de datos o un paquete completo descargable';require __DIR__.'/partials/header.php';
?>
<div class="backup-grid"><section class="admin-card backup-create"><span class="backup-icon">🛡️</span><h2>Crear nueva copia</h2><p>Genera una exportación SQL compatible con phpMyAdmin o un ZIP completo con base de datos y archivos subidos.</p><form method="post" class="admin-form-stack"><?=csrf_field()?><input type="hidden" name="action" value="create"><label class="backup-choice"><input type="radio" name="backup_type" value="database" checked><div><b>Base de datos</b><small>Usuarios, perfiles, productos, noticias, feedback, donaciones y configuración.</small></div></label><label class="backup-choice"><input type="radio" name="backup_type" value="complete"><div><b>Copia completa ZIP</b><small>SQL + imágenes y comprobantes almacenados en uploads.</small></div></label><label class="check-card"><input type="checkbox" name="include_config"> Incluir config.php <small>(contiene credenciales MySQL; guárdalo con máxima seguridad)</small></label><button class="admin-btn primary wide">➕ Crear copia ahora</button></form></section><section class="admin-card backup-guide"><h2>Qué se respalda</h2><ul><li>👥 Cuentas y perfiles de vendedores</li><li>📦 Artículos, categorías y fotografías</li><li>📰 Noticias, comentarios y feedback</li><li>💰 Donaciones y métodos configurados</li><li>🎨 Ajustes visuales y templates activos</li></ul><div class="admin-note">Las copias se guardan en <code>storage/backups</code>, una carpeta protegida. Descárgalas y almacénalas fuera del servidor.</div></section></div>
<section class="admin-card"><div class="panel-head"><div><h2>📚 Copias disponibles</h2><p><?=count($files)?> archivo(s) generado(s)</p></div></div><?php if($files):?><div class="backup-list"><?php foreach($files as $f):?><article><span class="backup-file-icon"><?=$f['type']==='zip'?'🗜️':'🗄️'?></span><div><b><?=e($f['name'])?></b><small><?=date('d/m/Y H:i',$f['time'])?> · <?=number_format($f['size']/1048576,2)?> MB</small></div><div class="backup-actions"><a class="admin-btn small success" href="?download=<?=urlencode($f['name'])?>">⬇ Descargar</a><form method="post" onsubmit="return confirm('¿Eliminar esta copia de seguridad?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="file" value="<?=e($f['name'])?>"><button class="admin-btn small danger">Eliminar</button></form></div></article><?php endforeach;?></div><?php else:?><div class="empty-admin">Todavía no has creado copias de seguridad.</div><?php endif;?></section>
<?php require __DIR__.'/partials/footer.php';?>
